import assert from "node:assert/strict";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { pathToFileURL } from "node:url";
import { build } from "esbuild";
import { JSDOM } from "jsdom";

// All document inputs and rendered outputs are generated by this test run.
// Never inspect existing user documents or persisted application state.
const dir = fs.mkdtempSync(path.join(os.tmpdir(), "deditor-table-lists-"));
fs.symlinkSync(path.resolve("node_modules"), path.join(dir, "node_modules"), "dir");
await build({
  entryPoints: ["src/lib/markdown.ts"],
  outfile: path.join(dir, "renderer.mjs"),
  bundle: true,
  packages: "external",
  platform: "node",
  format: "esm",
  plugins: [{
    name: "test-css",
    setup(b) {
      // Match Vite's CommonJS default interop while using the real plugin.
      b.onResolve({ filter: /^@vscode\/markdown-it-katex$/ }, () => ({ path: "katex", namespace: "test-katex" }));
      b.onLoad({ filter: /.*/, namespace: "test-katex" }, () => ({ contents:
        'import {createRequire} from "node:module"; const plugin = createRequire(import.meta.url)("@vscode/markdown-it-katex"); export default plugin.default ?? plugin;',
      }));
      b.onResolve({ filter: /\.css$/ }, () => ({ path: "css", namespace: "test-css" }));
      b.onLoad({ filter: /.*/, namespace: "test-css" }, () => ({ contents: "" }));
    },
  }],
});
const { renderMarkdown } = await import(pathToFileURL(path.join(dir, "renderer.mjs")));
const table = cell => `| 项目 | 内容 |\n| --- | --- |\n| 示例 | ${cell} |`;
let count = 0;
async function check(round, name, source, verify, theme = "light") {
  const input = path.join(dir, `${++count}.md`);
  fs.writeFileSync(input, source);
  const html = await renderMarkdown(fs.readFileSync(input, "utf8"), { theme });
  fs.writeFileSync(path.join(dir, `${count}-${theme}.html`), html);
  const dom = new JSDOM(html);
  try {
    verify(dom.window.document, html);
    console.log(`PASS round ${round}: ${name}`);
  } finally {
    dom.window.close();
  }
}

for (const marker of ["-", "+", "*"]) {
  await check(1, `${marker} bullet list`, table(`${marker} **第一项**<br>${marker} *第二项*`), doc => {
    assert.equal(doc.querySelectorAll("td ul > li").length, 2);
    assert.equal(doc.querySelector("td li strong").textContent, "第一项");
    assert.equal(doc.querySelector("td li em").textContent, "第二项");
  });
}
await check(1, "ordered list retains explicit numbers", table("3. 第一项<br />7. 第二项"), doc => {
  assert.equal(doc.querySelector("td ol").getAttribute("start"), "3");
  assert.deepEqual([...doc.querySelectorAll("td li")].map(li => li.getAttribute("value")), ["3", "7"]);
});
await check(1, "task list and inline formatting", table('- [ ] **待完成**<BR/>- [x] [完成](https://example.com)'), doc => {
  const boxes = [...doc.querySelectorAll("td input[type=checkbox]")];
  assert.deepEqual(boxes.map(box => [box.checked, box.disabled]), [[false, true], [true, true]]);
  assert.equal(doc.querySelector("td a").href, "https://example.com/");
});

for (const cell of ["", "-", "-1.25", "普通文本 - 说明", "`- 项目`", "\\- 项目", "`a<br>- b`", "``a`<br>- b``", "文本\\<br>- 项目", '<span title="<br>- 属性">文字</span>', "---", "# 标题"]) {
  await check(2, `literal cell ${JSON.stringify(cell)}`, table(cell), doc => {
    assert.equal(doc.querySelectorAll("td ul, td ol, td hr, td h1").length, 0);
  });
}
await check(2, "ordinary breaks remain visible inside list items", table("- 中文<br>续行<br>- 二"), doc => {
  assert.equal(doc.querySelectorAll("td li").length, 2);
  assert.equal(doc.querySelectorAll("td li:first-child br").length, 1);
});
await check(2, "code within lists remains literal", table("- `x<br>- y`<br>- z"), doc => {
  assert.equal(doc.querySelectorAll("td li").length, 2);
  assert.equal(doc.querySelector("td code").textContent, "x<br>- y");
});
await check(2, "large CJK cell", table("- " + "长文本".repeat(1000)), doc => {
  assert.equal(doc.querySelector("td li").textContent, "长文本".repeat(1000));
});

const combined = '# 标题\n\n- 外部列表\n\n| - 表头列表 | 格式 |\n| --- | ---: |\n| - 父项<br>  - 子项<br>- 第二项 | **粗体** / *斜体* / ~~删除~~ / `- 代码` |\n| - [ ] 待办<br>- [x] 完成 | ![图](./generated.png) |\n\n```js\nconst value = 1;\n```';
for (const theme of ["light", "dark"]) {
  await check(3, `combined rendering and source mapping (${theme})`, combined, doc => {
    assert.ok(doc.querySelector("th ul li"));
    assert.equal(doc.querySelectorAll("td ul ul li").length, 1);
    assert.deepEqual([...doc.querySelectorAll("tbody tr:first-child li")].map(li => li.getAttribute("data-line")), ["7", "7", "7"]);
    assert.ok(doc.querySelector('td[style="text-align:right"] strong'));
    assert.ok(doc.querySelector("td s"));
    assert.equal(doc.querySelector("td img").getAttribute("data-raw-src"), "./generated.png");
    assert.ok(doc.querySelector('pre.shiki[data-line="10"]'));
    assert.equal(doc.querySelector("body > ul li").textContent, "外部列表");
  }, theme);
}
await check(3, "reference links use document definitions", table("- [链接][ref]") + "\n\n[ref]: https://example.com", doc => {
  assert.equal(doc.querySelector("td li a").href, "https://example.com/");
});
await check(3, "math plugin and task lists coexist", table("- $x^2$<br>- [x] 完成"), doc => {
  assert.ok(doc.querySelector("td li .katex"));
  assert.ok(doc.querySelector("td li input:checked"));
});
await check(3, "subsequent plain table has no list state leakage", table("普通文字<br>第二行"), doc => {
  assert.equal(doc.querySelectorAll("td li").length, 0);
  assert.equal(doc.querySelectorAll("td br").length, 1);
});
console.log(`${count} passed; generated fixtures and HTML: ${dir}`);
